import numpy as np
from scipy.optimize import minimize

def f(vars):
    x, y, z = vars
    if x <= 0 or y <= 0 or z <= 0:
        return float('inf')
    return ((2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1)) / (x*y + y*z + z*x)

# Search over a grid of starting points
grid = np.logspace(-1, 1, 5) # 0.1 to 10
starts = []
for x in grid:
    for y in grid:
        for z in grid:
            starts.append([x, y, z])

min_val = float('inf')
for start in starts:
    res = minimize(f, start, bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
    if res.fun < min_val:
        min_val = res.fun

print(f"Absolute minimum found over grid: {min_val}")
